import { Request } from "../../request";
import { SinglePayload, DataRecordsQueryResult } from "../../types/payload";
import { Payload } from "../../types/payload";
import { Params } from "../../types/params";
/**
 * Data Tables admin methods. Wraps the `/v2/data-tables` API:
 * list/get tables and create/get/query/update/delete records.
 *
 * Responses are returned as the API sends them (wrapped in `{ data: ... }`),
 * consistent with the member methods.
 */
export default class DataTablesMethods extends Request {
    private endpoint;
    constructor(secretKey: string, test?: boolean, baseUrl?: string);
    /**
     * Lists every Data Table in the app, with each table's field definitions.
     *
     * @returns `{ data: { tables } }`
     *
     * @example
     * ```typescript
     * const { data } = await memberstack.dataTables.list();
     * for (const table of data.tables) console.log(table.key, table.fields.map(f => f.key));
     * ```
     */
    list(): Promise<SinglePayload<{
        tables: Payload.Transforms["DataTable"][];
    }>>;
    /**
     * Gets one Data Table by key or id, including its fields and access rules.
     *
     * @param params - `{ table }`
     * @param params.table - The table key (for example `"contacts"`) or id (`tbl_...`)
     * @returns `{ data: table }`
     *
     * @example
     * ```typescript
     * const { data: table } = await memberstack.dataTables.get({ table: 'contacts' });
     * console.log(table.fields);
     * ```
     */
    get(params: Params.GetDataTable): Promise<SinglePayload<Payload.Transforms["DataTable"]>>;
    /**
     * Creates a record in a table. Create the table and its fields in the dashboard first.
     *
     * @param params - `{ table, data, memberId? }`
     * @param params.table - The table key or id
     * @param params.data - Field values keyed by field key
     * @param params.memberId - Optionally link the record to a member of this app
     * @returns `{ data: record }`. `DECIMAL` values in the returned record are strings.
     *
     * @example
     * ```typescript
     * const { data: record } = await memberstack.dataTables.createRecord({
     *   table: 'contacts',
     *   data: { name: 'Ada Lovelace', score: 9.5, active: true },
     *   memberId: 'mem_...'
     * });
     * ```
     */
    createRecord(params: Params.CreateDataRecord): Promise<SinglePayload<Payload.Transforms["DataRecord"]>>;
    /**
     * Gets a single record by id. A convenience wrapper over a `findUnique` query.
     *
     * @param params - `{ table, recordId }`
     * @param params.table - The table key or id
     * @param params.recordId - The record id
     * @returns `{ data: { record } }`. Rejects with "Record not found" (404) when the id
     *   does not exist. `DECIMAL` values come back as numbers here.
     *
     * @example
     * ```typescript
     * const { data } = await memberstack.dataTables.getRecord({
     *   table: 'contacts',
     *   recordId: record.id
     * });
     * console.log(data.record.data.name);
     * ```
     */
    getRecord(params: Params.GetDataRecord): Promise<SinglePayload<{
        record: Payload.Transforms["DataRecord"];
    }>>;
    /**
     * Queries records with a Prisma-like `findMany` or `findUnique` query.
     *
     * @param params - `{ table, query }`
     * @param params.table - The table key or id
     * @param params.query - Exactly one of `{ findMany }` or `{ findUnique }`. `findMany`
     *   accepts `where`, `include`, `select`, `orderBy`, `take`, `skip`, `after` and `_count`.
     * @returns `{ data: { records, pagination } }` for `findMany`, `{ data: { record } }` for
     *   `findUnique`, or `{ data: { _count } }` for a pure count. `DECIMAL` values are numbers.
     *
     * @example Filter, sort and page
     * ```typescript
     * const { data } = await memberstack.dataTables.queryRecords({
     *   table: 'contacts',
     *   query: {
     *     findMany: {
     *       where: { active: { equals: true }, score: { gte: 5 } },
     *       orderBy: { score: 'desc' },
     *       take: 10
     *     }
     *   }
     * });
     * console.log(data.records.length, data.pagination?.hasMore);
     * ```
     */
    queryRecords(params: Params.QueryDataRecords): Promise<SinglePayload<DataRecordsQueryResult>>;
    /**
     * Updates a record. Only the fields you pass change.
     *
     * @param params - `{ table, recordId, data }`
     * @param params.table - The table key or id
     * @param params.recordId - The record id
     * @param params.data - Field values to change, keyed by field key
     * @returns `{ data: record }` with the updated record. `DECIMAL` values are strings.
     *
     * @example
     * ```typescript
     * await memberstack.dataTables.updateRecord({
     *   table: 'contacts',
     *   recordId: record.id,
     *   data: { score: 8 }
     * });
     * ```
     */
    updateRecord(params: Params.UpdateDataRecord): Promise<SinglePayload<Payload.Transforms["DataRecord"]>>;
    /**
     * Deletes a record permanently.
     *
     * @param params - `{ table, recordId }`
     * @param params.table - The table key or id
     * @param params.recordId - The record id
     * @returns `{ data: record }` with the record as it was before deletion
     *
     * @example
     * ```typescript
     * await memberstack.dataTables.deleteRecord({ table: 'contacts', recordId: record.id });
     * ```
     */
    deleteRecord(params: Params.DeleteDataRecord): Promise<SinglePayload<Payload.Transforms["DataRecord"]>>;
}
